// Generated by ts-rs from the solver's report and job structs (pkg/loopopt/src/ts_gen.rs): `./build.sh types`.
// Never edit it: change the Rust struct and regenerate. `./build.sh lint` fails when it is stale.

/**
 * Everything behind a loop's metric (`Model::detail`): the model's constants, each pair of members, each lineage.
 * Uma numbers index the loop's members.
 */
export type AffinityDetail = {
  /**
   * a parent legacy's inheritance rate before affinity (from the job's star mix)
   */
  base: number;
  /**
   * a grandparent's rate as a share of a parent's
   */
  gp_rate: number;
  /**
   * inheritance events per career
   */
  inspirations: number;
  /**
   * the chance an inherited white skill hint lands
   */
  gen_white: number;
  /**
   * the chance an inherited gold skill hint lands
   */
  gen_gold: number;
  pairs: Array<PairDetail>;
  lineages: Array<Lineage>;
};

/**
 * A deck job's answer.
 */
export type DeckReply = Refusal | Skyline | LoopReport;

/**
 * What the answer rests on.
 */
export type ExactSummary = {
  /**
   * the highest exact / product odds cap certified
   */
  rho: number;
  /**
   * the cap sought
   */
  rho_target: number;
  /**
   * the assumed cap per structure class (each certified at most at `rho`)
   */
  class_caps: [number, number, number, number];
  /**
   * the largest exact / product odds seen on any deck scored here
   */
  max_ratio: number;
  /**
   * the same per structure class
   */
  class_max_ratio: [number, number, number, number];
  /**
   * per structure class, the deck that reached `class_max_ratio` (null: none scored)
   */
  class_max_deck: [RatioDeck | null, RatioDeck | null, RatioDeck | null, RatioDeck | null];
  /**
   * the search ended by its stop rule (no unexamined loop or deck can win under the certified caps)
   */
  complete: boolean;
  decks_scored: number;
  deck_searches: number;
  loops_solved: number;
  schedule_rejects: number;
  /**
   * a scored deck reached its class's assumed cap
   */
  cap_hit: boolean;
  /**
   * an exact search stopped below the cap sought (its budget ran out)
   */
  budget_out: boolean;
  bound_filtered: number;
};

/**
 * Whose legacy a slot is.
 */
export type LegacyKind = 'parent' | 'grandparent';

/**
 * One legacy slot of a career.
 */
export type LegacySlot = {
  kind: LegacyKind;
  /**
   * [parent] or [parent, grandparent]
   */
  who: Array<number>;
  /**
   * relation points
   */
  rel: number;
  /**
   * the G1 wins shared (expected), as points
   */
  race: number;
  /**
   * affinity
   */
  aff: number;
  /**
   * the chance the slot's legacy is inherited per event
   */
  proc: number;
};

/**
 * One career of the loop: trainee `t` bred from parents `p`, who share grandparent `x`.
 */
export type Lineage = {
  /**
   * the trainee
   */
  t: number;
  /**
   * her parents
   */
  p: [number, number];
  /**
   * the grandparent both parents were bred from
   */
  x: number;
  /**
   * her six legacies: each parent, then that parent's two grandparents
   */
  slots: Array<LegacySlot>;
  /**
   * her chance of an inheritance per career
   */
  q: number;
  /**
   * the chance she lands every target, from the exact joint model
   */
  p_all: number;
  /**
   * the same chance in the model the search ranks by (each target's chance multiplied)
   */
  rank_value: number;
  /**
   * per uncertain target: her chance of landing it, and what her outfit gives of it
   */
  skills: Array<TargetChance>;
  /**
   * how many targets the job counts as gold already (`guaranteed` 2; left out of `skills`)
   */
  fixed_gold: number;
};

/**
 * A loop member as a result names her.
 */
export type LoopMember = {
  id: number;
  name: string;
  /**
   * her name shortened for chart columns
   */
  short: string;
};

/**
 * The loop search's report: the best loops with their decks, the search's counts, and what the answer rests on.
 */
export type LoopReport = {
  /**
   * the best loops, best first
   */
  top: Array<LoopResult>;
  /**
   * always empty (an older report's field)
   */
  best: [];
  /**
   * a deck per member (false: one deck for the loop)
   */
  per_uma: boolean;
  /**
   * loop structures the job's sizes and required umas allow
   */
  foursomes: number;
  /**
   * structures ranked by their ceiling
   */
  foursomes_ranked: number;
  /**
   * structures whose ceiling was read
   */
  foursomes_scanned: number;
  /**
   * structures whose schedules were solved
   */
  foursomes_solved: number;
  /**
   * the ceiling of everything left unsolved (0: nothing left)
   */
  next_bound: number;
  /**
   * the search ended by its stop rule: no unexamined loop can win
   */
  proven: boolean;
  /**
   * deck searches run: the first, and one per band
   */
  searches: number;
  exact: ExactSummary;
  /**
   * decks the enumeration built
   */
  decks_built: number;
  /**
   * decks on its nondominated frontier
   */
  decks_on_frontier: number;
  /**
   * cards that can hint a target
   */
  relevant_cards: number;
  /**
   * cards another card dominates, dropped before the enumeration
   */
  cards_dropped: number;
  /**
   * decks one card swap made from another
   */
  decks_swapped: number;
  /**
   * the plain pals (pals that hint no target), by name
   */
  plain_pals: Array<string>;
};

/**
 * One result of the loop search: the loop and its deck.
 */
export type LoopResult = {
  loop: ResultLoop;
  /**
   * the deck most members share (one deck for the loop: that deck)
   */
  deck: ResultDeck;
  /**
   * per member, when each has her own
   */
  decks?: Array<ResultDeck>;
};

/**
 * A member's outfit choice: the outfits that give it (none when it covers no target) and what it covers.
 */
export type MemberOutfits = { outfits: Array<OutfitLabel>; covers: Array<TargetCover> };

/**
 * An outfit by card id and label (id 0: any outfit).
 */
export type OutfitLabel = { id: number; label: string };

/**
 * A deck detached from the search that built it (names and ids instead of indices), for per-uma mode. Its names are
 * shared strings (`Name`: a skyline of 50k decks repeats about a hundred distinct ones), written as plain strings
 */
export type PDeck = {
  names: Array<string>;
  ids: Array<number>;
  ends: Array<number>;
  vars: Array<number>;
  choices: Array<string>;
  plain_ids: Array<number>;
  pal_names: Array<string>;
  pals: number;
  borrowed: string | null;
  dw: Array<number>;
  dg: Array<number>;
};

/**
 * Two members: their relation points and expected shared G1 wins.
 */
export type PairDetail = { a: number; b: number; rel: number; wins: number };

/**
 * A deck by its trainee and cards.
 */
export type RatioDeck = { trainee: number; cards: Array<string> };

/**
 * Why a job was not done (a bad request, a job outside the search's limits, nothing to search). Only a refusal
 * carries `error`, so `'error' in reply` tells it from a report.
 */
export type Refusal = { error: string };

/**
 * A deck in a result. Parallel lists: `cards[i]` is named with ` (borrowed)` or ` (end chain at link N)` appended
 * where that applies; `card_ids[i]` is its id (plain pals have a name but no id here: `plain_ids`).
 * It owns its lists: a result outlives the search that holds the deck.
 */
export type ResultDeck = {
  cards: Array<string>;
  card_ids: Array<number>;
  /**
   * the cards in it that are pals, by name
   */
  pal_cards: Array<string>;
  /**
   * per card with an id (`card_ids`' order): the chain link to end its story at (0: none)
   */
  end_chain_at: Array<number>;
  /**
   * per card with an id (`card_ids`' order): the skill to prioritise at its chain link
   */
  choices: Array<string>;
  /**
   * per uncertain target: the chance the deck hints its white skill, its gold
   */
  odds: Array<TargetHintOdds>;
  /**
   * the plain pals' ids
   */
  plain_ids: Array<number>;
  /**
   * how many pals it holds
   */
  pals: number;
  /**
   * the borrowed card, by name (null: none)
   */
  borrowed: string | null;
};

/**
 * A loop in a result; member k is `members[k]`, with `outfits[k]` and `per_trainee[k]`.
 */
export type ResultLoop = {
  members: Array<LoopMember>;
  /**
   * the chance every member lands every target, averaged over the loop's careers (what the results are ranked by)
   */
  p_all: number;
  /**
   * the chance each lands all but at most one
   */
  p_minus1: number;
  /**
   * the chance of landing exactly k targets, k = 0 ..= n, averaged over the loop's careers; null above the exact
   * engine's landed-set limit
   */
  landed: Array<number> | null;
  /**
   * the search's product value of this loop with these decks
   */
  rank_value: number;
  /**
   * per member: her outfits that cover a target, and what they cover
   */
  outfits: Array<MemberOutfits>;
  /**
   * per member: her chance of landing every target
   */
  per_trainee: Array<number>;
  /**
   * the mean inheritance chance per career
   */
  mean_proc: number;
  /**
   * the race schedule
   */
  schedule: Array<ScheduleRow>;
  /**
   * the affinity detail
   */
  detail: AffinityDetail;
};

/**
 * One member's attempt at a scheduled race.
 */
export type ScheduleCell = {
  /**
   * her win chance, in percent, rounded
   */
  p: number;
  /**
   * a goal race of her scenario
   */
  goal: boolean;
  /**
   * the aptitude cost (distance and surface grades), in percentage points
   */
  apt: number;
  /**
   * the career planner's low-aptitude cost (a race at the lowest aptitudes wins less than the table says), in
   * percentage points; the loop planner's cells have none
   */
  low?: number;
  /**
   * which race in a row this is (1 = the first)
   */
  row: number;
  /**
   * the penalty for racing several turns in a row, in percentage points (a goal race pays the previous position's)
   */
  pen: number;
};

/**
 * One scheduled G1, one cell per member (null: she doesn't run it).
 */
export type ScheduleRow = {
  /**
   * 0 Junior, 1 Classic, 2 Senior
   */
  year: number;
  /**
   * the turn, as "Cl E-Apr" (year, Early or Late, month)
   */
  when: string;
  /**
   * its name, shortened; "A/B" when either of two races runs at the same odds
   */
  race: string;
  /**
   * two or more members run it (it builds affinity); in a career's schedule, a parent won it
   */
  shared: boolean;
  cells: Array<ScheduleCell | null>;
  /**
   * how many members run it
   */
  runners: number;
  /**
   * the other race of an "A/B" pair (the career planner's rows: none)
   */
  alts: Array<string>;
};

/**
 * The nondominated deck frontier of a `deck_only` job.
 */
export type Skyline = { sky: Array<PDeck> };

/**
 * A trainee's chance of landing one uncertain target.
 */
export type TargetChance = {
  /**
   * the target's skill group
   */
  group: number;
  p: number;
  /**
   * what her outfit gives of it: 0 nothing, 1 the white skill, 2 the gold
   */
  outfit: number;
};

/**
 * What an outfit gives of a target: `level` 1 its white skill, 2 its gold.
 */
export type TargetCover = { group: number; level: number };

/**
 * A deck's hint odds for one target.
 */
export type TargetHintOdds = {
  /**
   * the target's skill group
   */
  group: number;
  white: number;
  gold: number;
};
